#include <Wire.h>  
#define PIN_MQ135 34    
#define PIN_MQ7   35    
#define PIN_BUZZER 14  // Inverted Logic (LOW = BEEP) 
#define PIN_LED    12   
const int MPU_ADDR = 0x68; 

int limit_gas = 3050;        
int limit_co  = 1500;        
float fall_threshold = 2.5;  

// GLOBAL V ARIABLES 
bool panic_latch = false;  
int val_gas = 0; 
int val_co = 0; 
float total_g = 0; 
String statusText = "SAFE"; 
String fallStatus = "SAFE"; 

// TIMERS 
unsigned long previousMillis = 0; 
bool buzzerState = false;  
unsigned long lastSerialPrint = 0; 
void setup() { 
  Serial.begin(115200); 

  // PINS 


  pinMode(PIN_MQ135, INPUT);  
  pinMode(PIN_MQ7, INPUT); 
  pinMode(PIN_BUZZER, OUTPUT);  
  pinMode(PIN_LED, OUTPUT); 

  digitalWrite(PIN_BUZZER, HIGH); // Silent (Inverted) 
  digitalWrite(PIN_LED, LOW); 

  // SENSORS 
  Wire.begin();  
  Wire.beginTransmission(MPU_ADDR); 
  Wire.write(0x6B);  
  Wire.write(0);     
  Wire.endTransmission(true);

digitalWrite(PIN_LED, LOW); 

  // SENSORS 
  Wire.begin();  
  Wire.beginTransmission(MPU_ADDR); 
  Wire.write(0x6B);  
  Wire.write(0);     
  Wire.endTransmission(true); 

  Serial.println("SYSTEM_READY"); 
} 
void loop() { 
  // --- A. READ SENSORS CONSTANTLY --- 
  val_gas = analogRead(PIN_MQ135); 
  val_co  = analogRead(PIN_MQ7); 

  Wire.beginTransmission(MPU_ADDR); 
  Wire.write(0x3B); Wire.endTransmission(false); 
  Wire.requestFrom(MPU_ADDR, 6, true);  
  int16_t AcX = Wire.read() << 8 | Wire.read(); 
  int16_t AcY = Wire.read() << 8 | Wire.read(); 
  int16_t AcZ = Wire.read() << 8 | Wire.read(); 



  float ax = AcX / 16384.0; float ay = AcY / 16384.0; float az = AcZ / 16384.0; 
  total_g = sqrt(pow(ax, 2) + pow(ay, 2) + pow(az, 2)); 

  // --- B. CHECK DANGER --- 
  if (total_g > fall_threshold) { 
    panic_latch = true;  
  } 

  bool gas_danger = (val_gas > limit_gas || val_co > limit_co); 
  bool alarm_active = (panic_latch || gas_danger);

if (total_g > fall_threshold) { 
    panic_latch = true;  
  } 

  bool gas_danger = (val_gas > limit_gas || val_co > limit_co); 
  bool alarm_active = (panic_latch || gas_danger); 

  statusText = gas_danger ? "DANGER" : "SAFE"; 
  fallStatus = panic_latch ? "FALL DETECTED" : "SAFE"; 

  // --- C. BEEPING LOGIC --- 
  if (alarm_active) { 
    unsigned long currentMillis = millis(); 
    if (currentMillis - previousMillis >= 200) { 
      previousMillis = currentMillis; 
      buzzerState = !buzzerState;  

      if (buzzerState) { 
        digitalWrite(PIN_BUZZER, LOW); // ON 
        digitalWrite(PIN_LED, HIGH);   // Light ON 
      } else { 
        digitalWrite(PIN_BUZZER, HIGH); // OFF 
        digitalWrite(PIN_LED, LOW);     // Light OFF 
      } 
    } 


  } else { 
    digitalWrite(PIN_BUZZER, HIGH);  
    digitalWrite(PIN_LED, LOW); 
  } 

  // --- D. SEND JSON OVER USB (Every 250ms) --- 
  if (millis() - lastSerialPrint > 250) {

} 


  } else { 
    digitalWrite(PIN_BUZZER, HIGH);  
    digitalWrite(PIN_LED, LOW); 
  } 

  // --- D. SEND JSON OVER USB (Every 250ms) --- 
  if (millis() - lastSerialPrint > 250) { 
    lastSerialPrint = millis(); 
    String json = "{"; 
    json += "\"gas\": " + String(val_gas) + ","; 
    json += "\"co\": " + String(val_co) + ","; 
    json += "\"fall\": \"" + fallStatus + "\","; 
    json += "\"val_g\": " + String(total_g) + ",";  
    json += "\"status\": \"" + statusText + "\""; 
    json += "}"; 
    Serial.println(json);  
  } 

  // --- E. RECEIVE RESET COMMAND FROM PYTHON --- 
  if (Serial.available() > 0) { 
    String cmd = Serial.readStringUntil('\n'); 
    cmd.trim(); 
    if (cmd == "RESET") { 
      panic_latch = false;  
      digitalWrite(PIN_BUZZER, HIGH); // Force Silence 
      digitalWrite(PIN_LED, LOW); 
    } 
  } 
} 


